INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q01_reset_soft', 'undo-and-recovery', 'medium', 'variant', 'You made the last {N} commits by mistake on `main`. Undo them but keep all changes staged.', '["git init", "for i in $(seq 1 {total_commits}); do echo \"content $i\" > file$i.txt && git add file$i.txt && git commit -m \"commit $i\"; done"]'::jsonb, 'head_offset(main)=={N} AND worktree_clean==true AND staged_files_count=={N}', '`git reset --soft HEAD~{N}` moves HEAD back {N} commits without touching the index or working tree, so all changes from those commits remain staged. `--hard` would destroy the changes, and `--mixed` would unstage them.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
INSERT INTO variants (id, template_id, variant_index, stem, params, explanation, status) VALUES ('3c5cf740-cc42-556a-800a-4188964312c1', 'q01_reset_soft', 1, 'You made the last 3 commits by mistake on `main`. Undo them but keep all changes staged.', '{"N": 3, "total_commits": 6}'::jsonb, '`git reset --soft HEAD~3` moves HEAD back 3 commits without touching the index or working tree, so all changes from those commits remain staged. `--hard` would destroy the changes, and `--mixed` would unstage them.', 'verified') ON CONFLICT (template_id, variant_index) DO UPDATE SET stem = EXCLUDED.stem, params = EXCLUDED.params;
