INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q02_branch_rename', 'branching', 'easy', 'variant', 'You want to rename the local branch `{old_name}` to `{new_name}` without switching to it. Which command does this?', '["git init", "echo ''initial'' > README.md && git add README.md && git commit -m ''initial commit''", "git branch {old_name}", "echo ''feature'' > feature.txt && git add feature.txt && git commit -m ''add feature''"]'::jsonb, 'branch_exists({new_name})==true AND branch_not_exists({old_name})==true AND current_branch==main', '`git branch -m <old> <new>` renames a branch without checking it out. Swapping the arguments renames in the wrong direction. `rename-branch` and `--rename` are not valid Git commands.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
