INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q03_rebase_count', 'rebasing', 'hard', 'variant', 'After rebasing `feature` onto `main`, how many total commits are reachable from `feature`? (Count the initial base commit.)', '["git init", "echo ''base'' > base.txt && git add base.txt && git commit -m ''base''", "git checkout -b feature", "for i in $(seq 1 {feature_commits}); do echo \"feat $i\" > feat$i.txt && git add feat$i.txt && git commit -m \"feature $i\"; done", "git checkout main", "for i in $(seq 1 {main_commits}); do echo \"main $i\" > main$i.txt && git add main$i.txt && git commit -m \"main $i\"; done", "git checkout feature", "git rebase main"]'::jsonb, 'commit_count(feature)=={total_after_rebase}', 'After rebase, `feature` has 1 (base) + {main_commits} (main) + {feature_commits} (replayed) = {total_after_rebase} commits.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
INSERT INTO variants (id, template_id, variant_index, stem, params, explanation, status) VALUES ('7c4fb97d-fbaf-5bc8-bd99-d94ba43ec542', 'q03_rebase_count', 1, 'After rebasing `feature` onto `main`, how many total commits are reachable from `feature`? (Count the initial base commit.)', '{"main_commits": 7, "feature_commits": 6}'::jsonb, 'After rebase, `feature` has 1 (base) + 7 (main) + 6 (replayed) = 14 commits.', 'verified') ON CONFLICT (template_id, variant_index) DO UPDATE SET stem = EXCLUDED.stem, params = EXCLUDED.params;
