INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q04_stash_apply', 'stashing', 'easy', 'variant', 'You have multiple stashes saved. You want to apply the stash at index {stash_idx} without dropping it from the list. Which command do you run?', '["git init", "echo ''base'' > app.js && git add app.js && git commit -m ''initial''", "echo ''stash2'' > f2.txt && git add f2.txt && git stash push -m ''stash2''", "echo ''stash1'' > f1.txt && git add f1.txt && git stash push -m ''stash1''", "echo ''stash0'' > f0.txt && git add f0.txt && git stash push -m ''stash0''"]'::jsonb, 'stash_count==3 AND file_exists(f{stash_idx}.txt)==true', '`git stash apply <index>` reapplies the changes recorded at stash index without removing the stash entry from the stash stack.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
INSERT INTO variants (id, template_id, variant_index, stem, params, explanation, status) VALUES ('81d36566-4691-5339-b9b2-7ce1471e8685', 'q04_stash_apply', 1, 'You have multiple stashes saved. You want to apply the stash at index 0 without dropping it from the list. Which command do you run?', '{"stash_idx": 0}'::jsonb, '`git stash apply <index>` reapplies the changes recorded at stash index without removing the stash entry from the stash stack.', 'verified') ON CONFLICT (template_id, variant_index) DO UPDATE SET stem = EXCLUDED.stem, params = EXCLUDED.params;
