INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q05_cherry_pick', 'advanced-git', 'medium', 'variant', 'You need to copy only the commit on `{feat_branch}` onto `main`. Which command applies this single commit?', '["git init", "echo ''v1'' > main.py && git add main.py && git commit -m ''initial''", "git checkout -b {feat_branch}", "echo ''wip'' > wip.py && git add wip.py && git commit -m ''wip feature''", "echo ''fix'' > hotfix.py && git add hotfix.py && git commit -m ''patch''", "git checkout main"]'::jsonb, 'commit_count(main)==2 AND file_exists(hotfix.py)==true AND current_branch==main', '`git cherry-pick <branch>` applies changes from a specific branch''s commit directly onto the current HEAD without merging branch histories.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
