INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q06_merge_conflict', 'merging', 'medium', 'variant', 'During a merge conflict on `{target_file}`, you decide to resolve it by keeping the incoming version from the branch being merged. Which command selects the incoming version for `{target_file}`?', '["git init", "echo ''base'' > README.md && git add README.md && git commit -m ''initial''", "git checkout -b feature", "echo ''incoming'' > {target_file} && git add {target_file} && git commit -m ''feature commit''", "git checkout main", "echo ''current'' > {target_file} && git add {target_file} && git commit -m ''main commit''", "git merge feature || true"]'::jsonb, 'file_content({target_file})==incoming', '`git checkout --theirs <file>` checks out the incoming version of a conflicting file during a merge conflict.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
