INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q08_revert_count', 'undo-and-recovery', 'medium', 'variant', 'You noticed an issue on public `main` and want to safely invert commit HEAD~{N} with a new commit. Which command should you run?', '["git init", "for i in $(seq 1 5); do echo \"c$i\" > f$i.txt && git add f$i.txt && git commit -m \"commit $i\"; done"]'::jsonb, 'reverted_commit(HEAD~{N})==true AND worktree_clean==true', '`git revert HEAD~K` creates a new commit that records the exact inverse of HEAD~K, safely undoing changes on shared branches without rewriting history.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
