INSERT INTO templates (id, topic, difficulty, type, stem_template, setup_commands, goal_predicate, explanation_template) VALUES ('q10_log_format', 'inspection', 'easy', 'variant', 'You want to inspect the commit history compactly on one line per commit, limited to the last {max_count} commits. Which command does this?', '["git init", "for i in $(seq 1 10); do echo \"c$i\" > f$i.txt && git add f$i.txt && git commit -m \"commit $i\"; done"]'::jsonb, 'last_command_stdout_lines=={max_count}', '`git log --oneline -n {max_count}` formats the commit log into one condensed line per commit and limits output to {max_count} entries.') ON CONFLICT (id) DO UPDATE SET stem_template = EXCLUDED.stem_template, goal_predicate = EXCLUDED.goal_predicate;
